mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.ASSET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ASSET_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.SYSTEM_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.GROUP_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.ASSET_ID = #{assetId}
AND T1.ASSET_NAME = #{assetName}
AND T1.SYSTEM_ID = #{systemId}
AND T1.GROUP_ID = #{groupId}
AND T1.ASSET_KIND_CD = #{assetKindCd}
AND T1.TECH_ROLE_CD = #{techRoleCd}
AND T1.ENV_CD = #{envCd}
AND T1.STATUS_CD = #{statusCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT 
      FROM TB_IF_SERVER_ASSET_PILOT T1

     ORDER BY T1.REG_DTM DESC, T1.ASSET_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

